/**
* Deterministic Hash Helper for Realistic Sector-Calibrated Metrics Across All 956+ JCI Emiten
*/
function hashTickerSeed(ticker) {
	let h = 2166136261;
	for (let i = 0; i < ticker.length; i++) {
		h ^= ticker.charCodeAt(i);
		h = Math.imul(h, 16777619);
	}
	return Math.abs(h);
}
