	const prefix = prefixes[seed % prefixes.length];
	const defaultRoe = Number((3.8 + seed % 78 / 10).toFixed(1));
	const defaultDer = Number((.58 + seed % 115 / 100).toFixed(2));
	const defaultOpMargin = Number((5.2 + seed % 85 / 10).toFixed(1));
	const approxPrice = Math.max(50, Math.round((95 + seed % 1400) / 5) * 5);
