	const adjustedAdtv20dIdr = userFundOverride?.adtv20dIdr && userFundOverride.adtv20dIdr > 0 ? Math.round(userFundOverride.adtv20dIdr) : Math.abs(splitRatioDivisor - 1) > 1e-4 ? Math.max(25e7, Math.round(rawAdtv20dIdr / Math.pow(splitRatioDivisor, .35))) : rawAdtv20dIdr;
