	const subIndustryEnum = input.subIndustry ?? catalogEntry?.subIndustry ?? resolvedStruct.subIndustry;
	const reasons = [];
	let classificationStage = "STAGE_1_STRUCTURAL";
	let classificationConfidence = "HIGH";
	let archetype = SUB_INDUSTRY_TO_ARCHETYPE_MAP[subIndustryEnum] || "CONSERVATIVE_FALLBACK";
	if (input.userSectorArchetypeOverride && SECTOR_PROFILES[input.userSectorArchetypeOverride]) {
		archetype = input.userSectorArchetypeOverride;
		classificationStage = "STAGE_0_USER_OVERRIDE";
		reasons.push(`User Override manual ke archetype ${archetype}`);
	} else reasons.push(`Stage 1 Struktural: IDX-IC '${sectorEnum}' -> Sub-Industri '${subIndustryEnum}' -> Archetype '${archetype}'`);
	let profile = SECTOR_PROFILES[archetype] || SECTOR_PROFILES.CONSERVATIVE_FALLBACK;
	const roeTTM = typeof input.roeTTM === "number" && Number.isFinite(input.roeTTM) ? input.roeTTM : 12;
	const roeAvg5Y = typeof input.roeMedian5YPct === "number" && Number.isFinite(input.roeMedian5YPct) ? input.roeMedian5YPct : typeof input.roeAvg5YPct === "number" && Number.isFinite(input.roeAvg5YPct) ? input.roeAvg5YPct : roeTTM;
	const kePct = typeof input.costOfEquityKePct === "number" && Number.isFinite(input.costOfEquityKePct) ? input.costOfEquityKePct : 11;
	const roicPct = typeof input.roicTTMPct === "number" && Number.isFinite(input.roicTTMPct) ? input.roicTTMPct : roeTTM;
	const roeSpread5Y = Math.abs(roeTTM - roeAvg5Y);
	const roeStd5Y = typeof input.roeStdDev5YPct === "number" && Number.isFinite(input.roeStdDev5YPct) ? input.roeStdDev5YPct : roeSpread5Y * .85;
	const earningsCv = typeof input.earningsCv5Y === "number" && Number.isFinite(input.earningsCv5Y) ? input.earningsCv5Y : roeStd5Y / Math.max(5, Math.abs(roeAvg5Y));
	const cyclicalityScore = Number(Math.min(100, Math.max(0, (profile.isCyclicalArchetype ? 55 : 20) + roeStd5Y * 2.2 + earningsCv * 18)).toFixed(1));
	const hasRealCapex = typeof input.capexTTMIdr === "number" && Number.isFinite(input.capexTTMIdr) && input.capexTTMIdr > 0;
	const hasRealDa = typeof input.daTTMIdr === "number" && Number.isFinite(input.daTTMIdr) && input.daTTMIdr > 0;
	const hasVerifiedCapexAndDa = input.hasVerifiedCapexAndDa !== void 0 ? input.hasVerifiedCapexAndDa : Boolean(hasRealCapex && hasRealDa && !input.isCoreFundamentalsSeed);
	const realCapexToDa = hasRealCapex && hasRealDa ? Number((input.capexTTMIdr / input.daTTMIdr).toFixed(2)) : null;
	const realCapexToRev = hasRealCapex && typeof input.revenueTTMIdr === "number" && input.revenueTTMIdr > 0 ? Number((input.capexTTMIdr / input.revenueTTMIdr).toFixed(2)) : null;
	const reportedCapexToDa = realCapexToDa ?? input.capexToDaRatio ?? 1;
	const reportedCapexToRev = realCapexToRev ?? input.capexToRevenueRatio ?? .04;
	const capitalIntensityScore = Number(Math.min(100, Math.max(0, reportedCapexToDa * 18 + reportedCapexToRev * 120)).toFixed(1));
