		for (let i = 1; i < stockCloses.length; i++) sRet.push((stockCloses[i] - stockCloses[i - 1]) / stockCloses[i - 1]);
		const mRet = [];
		for (let i = 1; i < jkseCloses.length; i++) mRet.push((jkseCloses[i] - jkseCloses[i - 1]) / jkseCloses[i - 1]);
		const overlapLen = Math.min(sRet.length, mRet.length, 60);
