/**
* Fetches live news, corporate actions, and specific issues for a given IDX ticker
* Strictly filters all news items to maximum 3 months (90 days) old.
*/
async function fetchLiveEmitenSpecificNews(rawTicker, companyName, sector, stockMetrics) {
	const cleanTicker = rawTicker.trim().toUpperCase().replace(/\.JK$/i, "").replace(/[^A-Z]/g, "").slice(0, 4);
	const catalogEntry = IDX_SECTOR_CATALOG.find((c) => c.ticker === cleanTicker) || createCalibratedIdxEntry(cleanTicker, sector, companyName);
	const resolvedName = companyName || stockMetrics?.name || catalogEntry.name;
	const resolvedSector = sector || stockMetrics?.sector || catalogEntry.sector;
	const liveFetchedItems = [];
	if (canUseExpressOnDemandApi()) try {
		const res = await fetch(`/api/news/emiten?ticker=${encodeURIComponent(cleanTicker)}&name=${encodeURIComponent(resolvedName)}`, { cache: "no-store" });
		if (res.ok) {
			const text = await res.text();
			const data = JSON.parse(text);
			recordSyncDiagnostic({
				ticker: cleanTicker,
				stage: "NEWS_RSS",
				endpoint: `/api/news/emiten?ticker=${cleanTicker}`,
				payloadBytes: text.length,
				httpStatus: res.status,
				status: "OK",
				errorDetail: `Express news endpoint mengembalikan ${(data?.items || []).length} artikel.`
			});
			if (Array.isArray(data?.items) && data.items.length > 0) for (const raw of data.items) {
				const cleanTitle = decodeHtmlEntities(String(raw.title || ""));
				const cleanSummary = raw.summary ? stripInlineCrossLinks(decodeHtmlEntities(String(raw.summary))) : void 0;
				const rawUrl = String(raw.url || "");
				if (!isNewsItemFreshWithin3Months(raw.publishedAt, cleanTitle, cleanSummary)) continue;
				if (!String(raw.source || "").includes("Yahoo Finance") && !isArticleStrictlyAboutEmiten(cleanTitle, rawUrl, cleanTicker, resolvedName, cleanSummary, raw.source)) continue;
				const { sentiment } = classifyHeadlineSentiment(cleanTitle, "DOMESTIC", cleanSummary);
				const emitenCategory = classifyEmitenNewsCategory(cleanTitle, cleanSummary);
				liveFetchedItems.push({
					id: raw.id || `em_${cleanTicker}_${liveFetchedItems.length}`,
					ticker: cleanTicker,
					title: cleanTitle,
					source: raw.source || `Radar ${cleanTicker}`,
					publishedAt: formatRecentNewsTimestamp(raw.publishedAt),
					url: rawUrl || `https://finance.yahoo.com/quote/${cleanTicker}.JK`,
					region: "DOMESTIC",
					summary: cleanSummary,
					sentiment,
					impactedSectors: [resolvedSector],
					emitenCategory
				});
			}
		}
	} catch {}
	if (liveFetchedItems.length === 0) try {
		const simpleQuery = `${cleanTicker} saham BEI when:90d`;
		const rssItems = await fetchRssFeedItems(`https://news.google.com/rss/search?q=${encodeURIComponent(simpleQuery)}&hl=id&gl=ID&ceid=ID:id`, `Google News BEI (${cleanTicker})`, "DOMESTIC", 8);
		for (const item of rssItems) {
			if (!isNewsItemFreshWithin3Months(item.publishedAt, item.title, item.summary)) continue;
			if (!isArticleStrictlyAboutEmiten(item.title, item.url, cleanTicker, resolvedName, item.summary, item.source)) continue;
			liveFetchedItems.push({
				...item,
				ticker: cleanTicker,
				impactedSectors: [resolvedSector],
				emitenCategory: classifyEmitenNewsCategory(item.title, item.summary)
			});
		}
	} catch {}
	const radarBaseline = buildEmitenCorporateActionRadarBaseline(cleanTicker, resolvedName, resolvedSector, stockMetrics);
	return [...liveFetchedItems, ...radarBaseline];
}
/**
* Strips any residual markdown bold/header markers (** or ###) so UI text is always clean.
*/
function stripRawMarkdownArtifacts(text) {
	return String(text || "").replace(/\*\*([^*]+)\*\*/g, "$1").replace(/\*\*/g, "").replace(/^#{1,4}\s+/gm, "").replace(/Nilai Intrinsik\s+Joeliardi-Graham/gi, "Nilai Intrinsik Wajar").replace(/Joeliardi-Graham/gi, "Nilai Intrinsik Wajar").replace(/prinsip\s+Joeliardi\s+Sunendar/gi, "disiplin Fundamental Kualitas Moat").replace(/kriteria\s+Joeliardi\s+Sunendar/gi, "kriteria Fundamental Kualitas Moat").replace(/\s*\(Joeliardi\s+Sunendar\)/gi, "").replace(/Joeliardi\s+Sunendar/gi, "Fundamental Kualitas Moat").replace(/\bPada kuotasi\b/gi, "Pada harga pasar").replace(/\bkuotasi\b/gi, "harga pasar").replace(/\bDiskon optik\b/gi, "Valuasi yang terlihat murah").replace(/\bdiskon optik\b/gi, "valuasi yang terlihat murah").replace(/\bsecara optik\b/gi, "di atas kertas").replace(/\bSecara kausal,\s*/gi, "Jika dibedah lebih dalam, ").replace(/\bsecara kausal\b/gi, "secara fundamental").replace(/\btrajektori harga\b/gi, "arah pergerakan harga").replace(/\btrajektori\b/gi, "arah pergerakan").replace(/\bpengungkit utang\b/gi, "rasio utang").replace(/\bpengungkit ekuitas\b/gi, "rasio pengali ekuitas").replace(/\bBermoat Kuat\b/gi, "Berdaya Saing Kuat").trim();
}
