/**
* Generates an on-demand Pre-Buy Fundamental & News Conviction Analysis.
* Uses Server-Side Gemini API (/api/ai/inspect-emiten) when available, with a deep multi-variable
* Chain-of-Thought analytical engine for GitHub Pages static mode.
*/
async function requestEmitenAiInspection(params) {
	const { stock, joeliardiEval, recentNews, userQuestion, regimeStatus, availablePortfolioCashIdr } = params;
	const fallbackReport = buildDeepAnalyticalConvictionReport(params);
	if (canUseExpressOnDemandApi()) try {
		const res = await fetch("/api/ai/inspect-emiten", {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({
				stock,
				joeliardiEval,
				recentNews,
				userQuestion,
				regimeStatus,
				availablePortfolioCashIdr
			})
		});
		if (res.ok) {
			const data = await res.json();
			if (data?.structuredReport && typeof data.structuredReport === "object") {
				const sr = data.structuredReport;
				const cleanedSummary = stripRawMarkdownArtifacts(sr.directAnswerSummary || fallbackReport.directAnswerSummary).replace(/^(Keputusan Komite atas pertanyaan Anda|Menjawab fokus Anda|Menjawab pertanyaan Anda)\s*(\([^)]*\))?\s*:\s*/i, "").trim();
				const enforcedCotSteps = (Array.isArray(sr.chainOfThoughtSteps) && sr.chainOfThoughtSteps.length > 0 ? sr.chainOfThoughtSteps.map(stripRawMarkdownArtifacts) : fallbackReport.chainOfThoughtSteps).map((step, idx) => {
					if (idx === 2 && joeliardiEval.isDefensiveDiscountAnomaly) return fallbackReport.chainOfThoughtSteps[2];
					return step;
				});
				const isCatalystBuyOverride = joeliardiEval.decisionState === "BUY_ON_STRENGTH_CATALYST";
				const sanitizedReport = {
					verdictBadge: fallbackReport.verdictBadge,
					verdictTitle: (joeliardiEval.isDefensiveDiscountAnomaly || isCatalystBuyOverride ? fallbackReport.verdictTitle : stripRawMarkdownArtifacts(sr.verdictTitle || fallbackReport.verdictTitle)).replace(/^Strong\s+Buy\s*[:—-]\s*/i, ""),
					directAnswerSummary: cleanedSummary || fallbackReport.directAnswerSummary,
					convictionScore: fallbackReport.convictionScore,
					chainOfThoughtSteps: enforcedCotSteps,
					sections: Array.isArray(sr.sections) && sr.sections.length > 0 ? sr.sections.map((sec, idx) => ({
						id: sec.id || `sec-${idx}`,
						badge: stripRawMarkdownArtifacts(sec.badge || `PILAR ${idx + 1}`),
						title: stripRawMarkdownArtifacts(sec.title || ""),
						keyMetricHighlight: stripRawMarkdownArtifacts(sec.keyMetricHighlight || ""),
						reasoningParagraph: stripRawMarkdownArtifacts(sec.reasoningParagraph || ""),
						bulletPoints: Array.isArray(sec.bulletPoints) ? sec.bulletPoints.map(stripRawMarkdownArtifacts) : [],
						sentimentTone: sec.sentimentTone || "NEUTRAL"
					})) : fallbackReport.sections,
					bullishDrivers: Array.isArray(sr.bullishDrivers) && sr.bullishDrivers.length > 0 ? sr.bullishDrivers.map(stripRawMarkdownArtifacts) : fallbackReport.bullishDrivers,
					bearishRisks: Array.isArray(sr.bearishRisks) && sr.bearishRisks.length > 0 ? sr.bearishRisks.map(stripRawMarkdownArtifacts) : fallbackReport.bearishRisks,
					executionStrategy: {
						recommendedAction: (joeliardiEval.isDefensiveDiscountAnomaly || isCatalystBuyOverride ? fallbackReport.executionStrategy.recommendedAction : stripRawMarkdownArtifacts(sr.executionStrategy?.recommendedAction || fallbackReport.executionStrategy.recommendedAction)).replace(/^Strong\s+Buy\s*[:—-]\s*/i, ""),
						idealEntryZone: fallbackReport.executionStrategy.idealEntryZone,
						InvalidationOrRiskLimit: stripRawMarkdownArtifacts(sr.executionStrategy?.InvalidationOrRiskLimit || fallbackReport.executionStrategy.InvalidationOrRiskLimit),
						portfolioAllocationGuide: fallbackReport.executionStrategy.portfolioAllocationGuide,
						isUndercutDeepDiscount: fallbackReport.executionStrategy.isUndercutDeepDiscount,
						isLiquidityCapped: fallbackReport.executionStrategy.isLiquidityCapped,
						liquidityWarningBadge: fallbackReport.executionStrategy.liquidityWarningBadge,
						adtv20dIdr: fallbackReport.executionStrategy.adtv20dIdr,
						maxSafeAllocationIdr: fallbackReport.executionStrategy.maxSafeAllocationIdr
					}
				};
				return {
					analysis: sanitizedReport.directAnswerSummary,
					structuredReport: sanitizedReport,
					isAiGenerated: true,
					generatedAt: data.generatedAt || (/* @__PURE__ */ new Date()).toISOString()
				};
			}
		}
	} catch {}
	return {
		analysis: fallbackReport.directAnswerSummary,
		structuredReport: fallbackReport,
		isAiGenerated: false,
		generatedAt: (/* @__PURE__ */ new Date()).toISOString()
	};
}
