	const rimPersistenceOmega = Number(Math.max(.56, Math.min(.88, rawOmega)).toFixed(2));
	const cashQualityAdj = isCapexTolerant && ocfToNi > .5 ? Math.max(.98, Math.min(1.08, .94 + ocfToNi * .14)) : Math.max(.78, Math.min(1.08, .88 + ocfToNi * .12 - accrualPenaltyScore * .05));
	const startRoePct = Math.max(2, Math.min(36, forwardRoePct * cashQualityAdj));
	const rimTerminalRoePct = Number(Math.max(kePct * .85, Math.min(kePct + 5.5, .55 * kePct + .45 * Math.min(22, startRoePct))).toFixed(2));
	const keDec = kePct / 100;
