/**
* Downloads the High-Definition PNG Image with Nostradamus Quant Terminal watermark
*/
function exportInspectToHdPng(payload) {
	const dataUrl = renderInspectorReportCanvas(payload).toDataURL("image/png", 1);
	const dateTag = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
	const link = document.createElement("a");
	link.download = `Nostradamus_Quant_Inspect_${payload.stock.ticker}_${dateTag}.png`;
	link.href = dataUrl;
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
}
/**
* Generates a standalone, standards-compliant PDF 1.4 file containing the High-DPI watermarked report
* on a single continuous proportional page and triggers a direct file download (.pdf).
*/
function exportInspectToPdf(payload) {
	const canvas = renderInspectorReportCanvas(payload);
	const base64Data = canvas.toDataURL("image/jpeg", .95).split(",")[1];
	const binaryStr = atob(base64Data);
	const imgBytes = new Uint8Array(binaryStr.length);
	for (let i = 0; i < binaryStr.length; i++) imgBytes[i] = binaryStr.charCodeAt(i);
	const imgW = canvas.width;
	const imgH = canvas.height;
	const pdfW = 842;
	const pdfH = Math.round(imgH / imgW * pdfW);
	const encoder = new TextEncoder();
	const chunks = [];
	const offsets = [];
	let byteLength = 0;
	const pushStr = (str) => {
		const bytes = encoder.encode(str);
		chunks.push(bytes);
		byteLength += bytes.length;
	};
	const pushBytes = (bytes) => {
		chunks.push(bytes);
		byteLength += bytes.length;
	};
	const startObj = (id) => {
		offsets[id] = byteLength;
		pushStr(`${id} 0 obj\n`);
	};
	pushStr("%PDF-1.4\n%ÿÿÿÿ\n");
	startObj(1);
	pushStr("<< /Type /Catalog /Pages 2 0 R >>\nendobj\n");
	startObj(2);
	pushStr("<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n");
	startObj(3);
	pushStr(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pdfW} ${pdfH}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>\nendobj\n`);
	startObj(4);
	pushStr(`<< /Type /XObject /Subtype /Image /Width ${imgW} /Height ${imgH} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${imgBytes.length} >>\nstream\n`);
	pushBytes(imgBytes);
	pushStr("\nendstream\nendobj\n");
	const contentStream = `q\n${pdfW} 0 0 ${pdfH} 0 0 cm\n/Im0 Do\nQ\n`;
	startObj(5);
	pushStr(`<< /Length ${contentStream.length} >>\nstream\n${contentStream}endstream\nendobj\n`);
	const xrefOffset = byteLength;
	pushStr("xref\n0 6\n0000000000 65535 f \n");
	for (let i = 1; i <= 5; i++) pushStr(`${String(offsets[i]).padStart(10, "0")} 00000 n \n`);
	pushStr(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`);
	const mergedBuffer = new ArrayBuffer(byteLength);
	const mergedView = new Uint8Array(mergedBuffer);
	let cursor = 0;
	for (const chunk of chunks) {
		mergedView.set(chunk, cursor);
		cursor += chunk.length;
	}
	const pdfBlob = new Blob([mergedBuffer], { type: "application/pdf" });
	const url = URL.createObjectURL(pdfBlob);
	const dateTag = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
	const link = document.createElement("a");
	link.href = url;
	link.download = `Nostradamus_Quant_Inspect_${payload.stock.ticker}_${dateTag}.pdf`;
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
	setTimeout(() => URL.revokeObjectURL(url), 5e3);
}
