function parseDirectSummaryHeaderAndBody(rawSummary) {
	const clean = String(rawSummary || "").trim();
	const match = clean.match(/^((?:Hasil|Kesimpulan|Keputusan|Evaluasi|Audit)\s+[^:]{3,75}):\s*([\s\S]*)$/i);
	if (match) {
		const rawHdr = match[1].trim();
		return {
			header: /Hasil Analisis Komite Investasi/i.test(rawHdr) ? "Hasil Analisis Nostradamus" : rawHdr,
			body: match[2].trim()
		};
	}
	const genericColon = clean.match(/^([^:]{5,55}):\s*([\s\S]+)$/);
	if (genericColon && !genericColon[1].includes(".")) {
		const rawHdr = genericColon[1].trim();
		return {
			header: /Hasil Analisis Komite Investasi/i.test(rawHdr) ? "Hasil Analisis Nostradamus" : rawHdr,
			body: genericColon[2].trim()
		};
	}
	return {
		header: "Hasil Analisis Nostradamus",
		body: clean
	};
}
function parseTitledCardStep(rawText, fallbackIndex) {
	const clean = String(rawText || "").trim();
	let header = null;
	let remainder = clean;
	const colonIdx = clean.indexOf(":");
	if (colonIdx > 0 && colonIdx <= 68) {
		header = clean.slice(0, colonIdx + 1).trim();
		remainder = clean.slice(colonIdx + 1).trim();
	} else if (typeof fallbackIndex === "number" && DEFAULT_COT_TITLES[fallbackIndex]) header = DEFAULT_COT_TITLES[fallbackIndex];
	const arrowMatch = remainder.split(/\s*(?:->|→)\s*/);
	if (arrowMatch.length > 1) {
		const bodyPart = arrowMatch.slice(0, -1).join(" → ").trim();
		const conclusionPart = arrowMatch[arrowMatch.length - 1].trim();
		return {
			header,
			body: bodyPart,
			conclusion: conclusionPart || null
		};
	}
	return {
		header,
		body: remainder,
		conclusion: null
	};
}
